package review

import (
	"encoding/json"
	"regexp"
	"strconv"
	"strings"

	reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
)

// trailFindingsJSONInstructions is the trail-mode output contract. Reviewers
// and the judge end with this JSON line so posting reads their findings
// structurally instead of interpreting prose. The example line must parse
// with splitTrailJSON; a test enforces that.
const trailFindingsJSONInstructions = `Final line (required, read by a program):
End your output with exactly one line holding only this JSON object, with no code fence and nothing after it:
{"summary":"one-sentence verdict","comments":[{"severity":"high","body":"bug; impact; fix","location":{"granularity":"line","file_path":"path/to/file.go","start_line":42}}]}
- Add one comment per actionable finding reported above, with the same severity: high, medium, or low.
- location.granularity is line (with start_line), range (with start_line and end_line), file, or whole_change.
- If nothing is actionable, use an empty array: "comments":[].
- This line is required even where other instructions say to output nothing else.`

// maxTrailJSONLines bounds the backward scan for a pretty-printed JSON block.
const maxTrailJSONLines = 200

// TrailComment is one finding in the trail JSON contract.
type TrailComment struct {
	Severity   string        `json:"severity"`
	Confidence *float64      `json:"confidence,omitempty"`
	Body       string        `json:"body"`
	Location   TrailLocation `json:"location"`
}

// TrailLocation anchors a TrailComment to the change.
type TrailLocation struct {
	Granularity  string `json:"granularity"`
	FilePath     string `json:"file_path,omitempty"`
	StartLine    int    `json:"start_line,omitempty"`
	EndLine      int    `json:"end_line,omitempty"`
	SelectedText string `json:"selected_text,omitempty"`
}

// TrailReport is what a trail-mode run posts: structured comments from
// reviews that honored the JSON contract, and the prose, with any contract
// line removed, of those that did not. At least one of the two is set.
type TrailReport struct {
	Comments []TrailComment
	Prose    string
}

// trailReportFor decides what a trail-mode run posts. It returns post=false
// only when the JSON contract reports no findings and nothing in the prose
// contradicts that; every malformed or contradictory case posts, so a
// misbehaving model costs an extra finding rather than a lost one. A posted
// report is empty only when the output had nothing readable. When a judge
// ran, its verdict decides: it is asked to drop unsupported claims.
func trailReportFor(summary reviewtypes.RunSummary, aggregateOutput string) (TrailReport, bool) {
	if verdict := strings.TrimSpace(aggregateOutput); verdict != "" {
		prose, comments, ok := splitTrailJSON(verdict)
		if !contractCoversProse(prose, comments, ok) {
			if prose == "" {
				// A JSON-only reply without a summary has no prose of its own.
				prose = combinedReviewNarratives(usableAgentRuns(summary))
			}
			return TrailReport{Prose: prose}, true
		}
		return TrailReport{Comments: comments}, len(comments) > 0
	}
	var merged []TrailComment
	var unstructured []reviewtypes.AgentRun
	for _, run := range usableAgentRuns(summary) {
		prose, comments, ok := splitTrailJSON(reportText(run.Buffer))
		if !contractCoversProse(prose, comments, ok) {
			unstructured = append(unstructured, run)
			continue
		}
		merged = append(merged, comments...)
	}
	report := TrailReport{Comments: merged, Prose: combinedReviewNarratives(unstructured)}
	return report, len(merged) > 0 || len(unstructured) > 0
}

// contractCoversProse reports whether a valid contract can be posted in place
// of its prose: the prose reports no finding the comments leave out. That
// means no more severity-marked findings than comments, and no file:line the
// comments do not cover; locations catch a finding however the prose is laid
// out. The prose normally repeats every comment, so it is posted instead of,
// not alongside, an incomplete contract.
func contractCoversProse(prose string, comments []TrailComment, ok bool) bool {
	if !ok {
		return false
	}
	if len(comments) == 0 {
		return !proseReportsFindings(prose)
	}
	return markedFindingCount(prose) <= len(comments) && locationsCovered(prose, comments)
}

// LocationPattern matches a file:line reference such as "retry.go:42".
var LocationPattern = regexp.MustCompile("(?:^|[\\s(`])([A-Za-z0-9_./-]+\\.[A-Za-z0-9_+-]+):(\\d+)")

// locationsCovered reports whether every file:line the prose cites falls in a
// comment's location on the same file or is cited in a comment's body.
func locationsCovered(prose string, comments []TrailComment) bool {
	for _, match := range LocationPattern.FindAllStringSubmatch(prose, -1) {
		path := match[1]
		line, err := strconv.Atoi(match[2])
		if err != nil {
			continue
		}
		if !locationCovered(path, line, comments) {
			return false
		}
	}
	return true
}

func locationCovered(path string, line int, comments []TrailComment) bool {
	ref := path + ":" + strconv.Itoa(line)
	for _, comment := range comments {
		if strings.Contains(comment.Body, ref) {
			return true
		}
		loc := comment.Location
		if !samePath(loc.FilePath, path) || loc.StartLine <= 0 {
			continue
		}
		if line >= loc.StartLine && line <= max(loc.EndLine, loc.StartLine) {
			return true
		}
	}
	return false
}

// samePath reports whether two paths name the same file, allowing one to be
// a shorter suffix of the other ("retry.go" and "internal/retry.go").
func samePath(a, b string) bool {
	a, b = strings.TrimPrefix(a, "./"), strings.TrimPrefix(b, "./")
	if a == "" || b == "" {
		return false
	}
	return a == b || strings.HasSuffix(a, "/"+b) || strings.HasSuffix(b, "/"+a)
}

// markedFindingCount counts the findings prose reports with a severity, the
// finding shape the output format asks for: lines at any indentation, list
// items included, that open with a severity marker, and findings without one
// under a severity heading.
func markedFindingCount(prose string) int {
	count := 0
	for _, line := range strings.Split(prose, "\n") {
		if _, _, ok := severityGroupLabel(line); ok {
			continue
		}
		trimmed := strings.TrimSpace(line)
		if item, ok := ListItemText(trimmed); ok {
			trimmed = item
		}
		if StartsWithSeverityMarker(trimmed) {
			count++
		}
	}
	for _, finding := range SplitProseFindings(prose) {
		if finding.Severity != "" && !StartsWithSeverityMarker(finding.Text) {
			count++
		}
	}
	return count
}

// reportText returns a reviewer's report: the last stretch of text between
// tool calls that ends with a valid contract line, or "" if none does. It is
// found by the contract line rather than by position, so a tool call after
// the report does not hide it, and earlier exploration narration, whose
// bullets ("I'll check:\n- retry.go") are not findings, is left out. A tool
// call inside a message, where the next text continues it as a delta, is not
// a boundary. A stretch holding only the contract line also takes the latest
// text before it that reports findings by more than bullets, so a report
// written before the final tool calls is still checked against the line while
// a bulleted file list is not.
func reportText(buf []reviewtypes.Event) string {
	end := len(buf)
	for i := len(buf) - 1; i >= -1; i-- {
		if i >= 0 && !isTextBoundary(buf, i) {
			continue
		}
		text := joinAssistantText(buf[i+1 : end])
		prose, payload, found := splitTrailJSONPayload(text)
		if _, ok := decodeTrailComments(payload["comments"]); !found || !ok {
			end = i
			continue
		}
		if prose == "" && i >= 0 {
			if before := lastMarkedReportBefore(buf, i); before != "" {
				return before + "\n\n" + text
			}
		}
		return text
	}
	return ""
}

// lastMarkedReportBefore returns the latest stretch of text before buf[end]
// that reports findings by more than bullets, or "" if none does.
func lastMarkedReportBefore(buf []reviewtypes.Event, end int) string {
	for i := end - 1; i >= -1; i-- {
		if i >= 0 && !isTextBoundary(buf, i) {
			continue
		}
		if text := joinAssistantText(buf[i+1 : end]); proseReportsMarkedFindings(text) {
			return text
		}
		end = i
	}
	return ""
}

// isTextBoundary reports whether buf[i] is a tool call that separates two
// stretches of text rather than interrupting a message.
func isTextBoundary(buf []reviewtypes.Event, i int) bool {
	_, ok := buf[i].(reviewtypes.ToolCall)
	return ok && !continuesMessage(buf[i+1:])
}

// continuesMessage reports whether the first text in buf continues the
// message before it.
func continuesMessage(buf []reviewtypes.Event) bool {
	for _, ev := range buf {
		if at, ok := ev.(reviewtypes.AssistantText); ok {
			return at.Delta
		}
	}
	return false
}

// splitTrailJSON separates a trailing contract-shaped JSON object (one line,
// a fenced block, or a pretty-printed block, with a "summary" or "comments"
// key) from the prose before it, so a malformed contract is never posted as
// finding text. Other trailing JSON, such as a config snippet quoted as
// evidence, stays in the prose. A JSON-only reply contributes its summary as
// the prose instead. ok reports a valid contract: a "comments" array.
// Entries without a body are dropped.
func splitTrailJSON(text string) (prose string, comments []TrailComment, ok bool) {
	prose, payload, found := splitTrailJSONPayload(text)
	if !found {
		return prose, nil, false
	}
	if prose == "" {
		var summary string
		if json.Unmarshal(payload["summary"], &summary) == nil {
			prose = strings.TrimSpace(summary)
		}
	}
	comments, ok = decodeTrailComments(payload["comments"])
	return prose, comments, ok
}

// splitTrailJSONPayload finds a trailing contract-shaped JSON object and
// returns the prose before it and its decoded keys. found is false, with
// the whole text as prose, when there is none.
func splitTrailJSONPayload(text string) (prose string, payload map[string]json.RawMessage, found bool) {
	text = strings.TrimSpace(text)
	lines := strings.Split(text, "\n")
	end := len(lines)
	fenced := end > 1 && strings.TrimSpace(lines[end-1]) == "```"
	if fenced {
		end--
	}
	for start := end - 1; start >= 0 && start >= end-maxTrailJSONLines; start-- {
		if !strings.HasPrefix(strings.TrimSpace(lines[start]), "{") {
			continue
		}
		payload = nil
		if err := json.Unmarshal([]byte(strings.Join(lines[start:end], "\n")), &payload); err != nil {
			continue
		}
		_, hasSummary := payload["summary"]
		_, hasComments := payload["comments"]
		if !hasSummary && !hasComments {
			break
		}
		proseEnd := start
		if fenced && proseEnd > 0 && strings.HasPrefix(strings.TrimSpace(lines[proseEnd-1]), "```") {
			proseEnd--
		}
		return strings.TrimSpace(strings.Join(lines[:proseEnd], "\n")), payload, true
	}
	return text, nil, false
}

func decodeTrailComments(raw json.RawMessage) ([]TrailComment, bool) {
	if !strings.HasPrefix(strings.TrimSpace(string(raw)), "[") {
		return nil, false
	}
	var decoded []TrailComment
	if err := json.Unmarshal(raw, &decoded); err != nil {
		return nil, false
	}
	comments := []TrailComment{}
	for _, comment := range decoded {
		if strings.TrimSpace(comment.Body) != "" {
			comments = append(comments, comment)
		}
	}
	return comments, true
}

// stripTrailJSON removes a valid trailing contract line for display. Only a
// run that asked for the line has one; elsewhere a trailing JSON block is the
// reviewer's own text and stays.
func stripTrailJSON(text string, trailFindingsJSON bool) string {
	if !trailFindingsJSON {
		return text
	}
	if prose, _, ok := splitTrailJSON(text); ok {
		return prose
	}
	return text
}

// proseReportsFindings reports whether prose contradicts an empty comments
// array: a list item at any indentation, or a finding proseReportsMarkedFindings
// recognizes. These are the shapes the output format asks for, so a clean
// review has none of them. A list item that only says a section is empty
// ("- None") is not a finding.
func proseReportsFindings(prose string) bool {
	for _, line := range strings.Split(prose, "\n") {
		if item, ok := ListItemText(strings.TrimSpace(line)); ok && !isNoFindingsText(item) {
			return true
		}
	}
	return proseReportsMarkedFindings(prose)
}

// proseReportsMarkedFindings reports whether prose reports findings by more
// than bullets: a severity marker or feedback label such as "Nits:" at any
// indentation, a finding under a severity heading, or a verdict, labeled or
// not, that itself says there is feedback. A bulleted file list in
// exploration narration has none of these.
func proseReportsMarkedFindings(prose string) bool {
	for _, line := range strings.Split(prose, "\n") {
		if _, _, ok := severityGroupLabel(line); ok {
			continue
		}
		trimmed := strings.TrimSpace(line)
		if item, ok := ListItemText(trimmed); ok {
			trimmed = item
		}
		lower := strings.ToLower(trimMarkdownEmphasis(trimmed))
		if after, found := strings.CutPrefix(lower, "verdict"); found {
			lower = trimMarkdownEmphasis(strings.TrimLeft(after, ":-—– "))
		}
		if StartsWithSeverityMarker(lower) {
			return true
		}
		for _, prefix := range []string{
			"request changes", "request_changes", "changes requested", "approve with nits",
			"needs changes", "needs work", "changes needed",
			"nits:", "issues:", "concerns:", "suggestions:", "findings:", "problems:", "blocking:",
		} {
			if strings.HasPrefix(lower, prefix) {
				return true
			}
		}
	}
	return markedFindingCount(prose) > 0
}

func trimMarkdownEmphasis(s string) string {
	return strings.TrimLeft(s, "#>*_` ")
}

// StartsWithSeverityMarker reports whether line, after leading Markdown
// emphasis, opens with a severity tag: bracketed ("[high]"), delimited
// ("high —", "p2:"), closed by emphasis ("**High** ..."), or alone (a "### High"
// heading). A word that merely starts with a marker ("Highlights") is not one.
func StartsWithSeverityMarker(line string) bool {
	return LeadingSeverity(line) != ""
}

// LeadingSeverity returns the severity tag line opens with, in lower case, as
// StartsWithSeverityMarker recognizes it, or "" if there is none.
func LeadingSeverity(line string) string {
	lower := strings.ToLower(trimMarkdownEmphasis(strings.TrimSpace(line)))
	for _, marker := range severityMarkers {
		if strings.HasPrefix(lower, "["+marker+"]") {
			return marker
		}
		rest, found := strings.CutPrefix(lower, marker)
		if !found {
			continue
		}
		if strings.TrimSpace(rest) == "" {
			return marker
		}
		for _, suffix := range []string{" —", " –", " -", ":", "*", "_"} {
			if strings.HasPrefix(rest, suffix) {
				return marker
			}
		}
	}
	return ""
}

var severityMarkers = []string{"critical", "high", "medium", "low", "p0", "p1", "p2", "p3", "nit"}

// severityGroupLabel reports whether line, unindented, labels a group of
// findings by severity and returns the label in lower case and the heading
// level (0 for a label that is not a "#" heading): a line holding only a
// severity ("### High", "**Low:**", "Nits:"), or a heading whose first word is
// one followed by a delimiter or a qualifier ("### High severity",
// "## P1 — must fix"). "## High Level Summary" is not one.
func severityGroupLabel(line string) (string, int, bool) {
	level := headingLevel(line)
	if label, ok := severityLabel(line); ok {
		return label, level, true
	}
	if level == 0 {
		return "", 0, false
	}
	words := strings.Fields(strings.TrimLeft(line, "#"))
	if len(words) == 0 {
		return "", 0, false
	}
	label, ok := severityLabel(words[0])
	if !ok {
		return "", 0, false
	}
	if len(words) == 1 || strings.HasSuffix(words[0], ":") || isSeverityQualifier(words[1]) {
		return label, level, true
	}
	return "", 0, false
}

func isSeverityQualifier(word string) bool {
	word = strings.ToLower(strings.Trim(word, "*_`:"))
	if strings.HasPrefix(word, "(") {
		return true
	}
	switch word {
	case "—", "–", "-", "severity", "priority", "issues", "findings", "risk":
		return true
	}
	return false
}

// detailLabels are labels that add detail to or sum up the finding before
// them rather than starting one.
var detailLabels = map[string]bool{
	"fix": true, "impact": true, "problem": true, "issue": true, "why": true,
	"evidence": true, "suggestion": true, "recommendation": true, "note": true,
	"location": true, "file": true, "files": true, "details": true, "description": true,
	"context": true, "cause": true, "root cause": true, "rationale": true, "example": true,
	"repro": true, "reproduction": true, "severity": true, "priority": true, "risk": true,
	"confidence": true, "summary": true, "verdict": true, "overall": true, "conclusion": true,
}

// opensWithDetailLabel reports whether text opens with a detail label
// ("**Fix:** ...", "Impact: ...", "**Summary**: ...", "Recommended fix:") or
// is one alone.
func opensWithDetailLabel(text string) bool {
	label, _, _ := strings.Cut(strings.TrimLeft(text, "#*_` "), ":")
	label = strings.ToLower(strings.Trim(label, "*_` "))
	return detailLabels[label] || strings.HasSuffix(label, " fix")
}

// isLabelTitle reports whether a sub-heading title only names a category or
// file ("Correctness", "`retry.go`") rather than stating a finding.
func isLabelTitle(title string) bool {
	if item, ok := ListItemText(title); ok {
		title = item
	}
	words := 0
	for i, part := range strings.Split(title, "`") {
		if i%2 == 0 {
			words += len(strings.Fields(strings.Trim(part, "*_:()")))
		}
	}
	return words <= 1
}

// headingLevel returns the level of an unindented Markdown "#" heading, or 0.
func headingLevel(line string) int {
	level := len(line) - len(strings.TrimLeft(line, "#"))
	if level == 0 || !strings.HasPrefix(line[level:], " ") {
		return 0
	}
	return level
}

// severityLabel reports whether line, unindented, holds only a severity
// label ("### High", "**Low:**", "Nits:") and returns it in lower case.
func severityLabel(line string) (string, bool) {
	if line != strings.TrimLeft(line, " \t") {
		return "", false
	}
	label := strings.TrimLeft(strings.TrimSpace(line), "#>*_`[ ")
	label = strings.ToLower(strings.TrimRight(label, ":*_`] "))
	for _, marker := range severityMarkers {
		if label == marker || label == marker+"s" {
			return label, true
		}
	}
	return "", false
}

var noFindingsPattern = regexp.MustCompile(`^(none|nothing|n/?a|no (\S+ ){0,3}(issues|findings|concerns|problems))( (found|identified|noted|to report))?$`)

// isNoFindingsText reports whether text only says a section is empty
// ("None.", "No high-severity issues."), as reviews often write under a
// severity heading with nothing in it.
func isNoFindingsText(text string) bool {
	return noFindingsPattern.MatchString(strings.ToLower(strings.Trim(text, "*_`.!:() \t")))
}

// ProseFinding is one top-level finding in prose. Severity is the label of
// the severity heading it sits under ("high", "p2"), or "" outside one.
type ProseFinding struct {
	Text     string
	Severity string
}

// SplitProseFindings splits prose into its top-level findings: list items and
// lines that open with a severity marker, each with the lines that continue
// it. A severity group label ("### High", "**Low:**", "## P1 — must fix")
// groups the findings below it rather than being one. In a group, text that is
// not a list item is a finding too, and a deeper heading or a bold paragraph
// starts a new one. List items under a sub-heading that states a finding are
// its details; under one that only names a category or file ("Correctness",
// "`retry.go`") they are findings and the title is dropped. A line opening
// with a detail label such as "Fix:" or "**Summary:**" continues the finding
// before it. A group ends at a
// heading at its level or above, a "Summary"-style sub-heading, or a
// placeholder such as "None." directly under its label, so a closing summary
// is not a finding; a placeholder under a sub-heading drops only that
// sub-heading. Trail posting counts findings with this and the bridge posts
// them, so both agree on what a finding is.
func SplitProseFindings(prose string) []ProseFinding {
	var findings []ProseFinding
	var current strings.Builder
	group, groupLevel := "", 0
	afterBlank := false
	// headingOnly marks that the current finding holds only a sub-heading's
	// title so far; headingDetails marks that the list items under that
	// title are its details.
	headingOnly, headingDetails := false, false
	flush := func() {
		text := strings.TrimSpace(current.String())
		current.Reset()
		headingOnly, headingDetails = false, false
		if text != "" {
			findings = append(findings, ProseFinding{Text: text, Severity: group})
		}
	}
	appendLine := func(line string) {
		if current.Len() > 0 {
			current.WriteByte('\n')
		}
		current.WriteString(line)
		if strings.TrimSpace(line) != "" {
			headingOnly = false
		}
	}
	for _, line := range strings.Split(strings.TrimSpace(prose), "\n") {
		blank := strings.TrimSpace(line) == ""
		paragraphStart := afterBlank
		afterBlank = blank
		if label, level, ok := severityGroupLabel(line); ok {
			flush()
			group, groupLevel = label, level
			continue
		}
		if level := headingLevel(line); level > 0 && group != "" {
			flush()
			title := strings.TrimSpace(strings.TrimLeft(line, "#"))
			if groupLevel > 0 && level > groupLevel && !opensWithDetailLabel(title) {
				current.WriteString(title)
				headingOnly = true
			} else {
				group = ""
			}
			continue
		}
		item, isItem := topLevelListItemText(line)
		if headingOnly && ((isItem && isNoFindingsText(item)) || (!isItem && isNoFindingsText(line))) {
			current.Reset()
			headingOnly = false
			continue
		}
		if current.Len() > 0 && opensWithDetailLabel(strings.TrimSpace(line)) {
			appendLine(line)
			continue
		}
		if isItem && headingOnly {
			if isLabelTitle(strings.TrimSpace(current.String())) {
				current.Reset()
				headingOnly = false
			} else {
				headingDetails = true
			}
		}
		if isItem && current.Len() > 0 && (headingDetails || opensWithDetailLabel(item)) {
			appendLine(line)
			continue
		}
		if isItem {
			flush()
			if isNoFindingsText(item) {
				group = ""
			} else {
				current.WriteString(item)
			}
			continue
		}
		if line == strings.TrimLeft(line, " \t") && StartsWithSeverityMarker(line) {
			flush()
			current.WriteString(strings.TrimSpace(line))
			continue
		}
		if group != "" && paragraphStart && strings.HasPrefix(line, "**") {
			flush()
		}
		if current.Len() == 0 {
			if group == "" || blank {
				continue
			}
			if isNoFindingsText(line) {
				group = ""
				continue
			}
		}
		appendLine(line)
	}
	flush()
	return findings
}

func topLevelListItemText(line string) (string, bool) {
	if line != strings.TrimLeft(line, " \t") {
		return "", false
	}
	item, ok := ListItemText(strings.TrimSpace(line))
	return item, ok && item != ""
}

// ListItemText returns the text of a Markdown list item ("- ", "* ", "+ ",
// "• ", "1. ", "1) ") and whether trimmed, a line without surrounding space,
// is one.
func ListItemText(trimmed string) (string, bool) {
	for _, bullet := range []string{"- ", "* ", "+ ", "• "} {
		if item, found := strings.CutPrefix(trimmed, bullet); found {
			return strings.TrimSpace(item), true
		}
	}
	digits := len(trimmed) - len(strings.TrimLeft(trimmed, "0123456789"))
	if digits == 0 {
		return "", false
	}
	for _, delim := range []string{". ", ") "} {
		if item, found := strings.CutPrefix(trimmed[digits:], delim); found {
			return strings.TrimSpace(item), true
		}
	}
	return "", false
}

